/**
 * Role inference system tests (F8: Pairing splash QR)
 *
 * Tests URL hash parsing, mode detection, and deep link generation
 * for the sender/receiver role switching functionality.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import {
  AppMode,
  parseModeFromHash,
  getCurrentMode,
  generateReceiverLink,
  generateSenderLink,
  switchToReceiverMode,
  switchToSenderMode,
} from '../src/platform/role-inference.js';

describe('role-inference', () => {
  describe('parseModeFromHash', () => {
    it('should parse #recv hash as receiver mode', () => {
      expect(parseModeFromHash('#recv')).toBe(AppMode.RECEIVER);
      expect(parseModeFromHash('#RECV')).toBe(AppMode.RECEIVER);
    });

    it('should parse #receive hash as receiver mode', () => {
      expect(parseModeFromHash('#receive')).toBe(AppMode.RECEIVER);
      expect(parseModeFromHash('#RECEIVE')).toBe(AppMode.RECEIVER);
    });

    it('should parse #send hash as sender mode', () => {
      expect(parseModeFromHash('#send')).toBe(AppMode.SENDER);
      expect(parseModeFromHash('#SEND')).toBe(AppMode.SENDER);
    });

    it('should parse empty hash as receiver mode (default)', () => {
      expect(parseModeFromHash('')).toBe(AppMode.RECEIVER);
      expect(parseModeFromHash('#')).toBe(AppMode.RECEIVER);
    });

    it('should parse unknown hash as receiver mode (default)', () => {
      expect(parseModeFromHash('#unknown')).toBe(AppMode.RECEIVER);
      expect(parseModeFromHash('#foo')).toBe(AppMode.RECEIVER);
    });

    it('should handle hash without leading #', () => {
      expect(parseModeFromHash('recv')).toBe(AppMode.RECEIVER);
      expect(parseModeFromHash('send')).toBe(AppMode.SENDER);
    });
  });

  describe('generateReceiverLink', () => {
    it('should generate URL with #recv hash', () => {
      // Mock window.location
      const originalLocation = window.location;
      delete (window as any).location;
      window.location = new URL('https://example.com/screenferry') as any;

      const link = generateReceiverLink();
      expect(link).toContain('#recv');

      window.location = originalLocation;
    });

    it('should preserve existing URL components', () => {
      const originalLocation = window.location;
      delete (window as any).location;
      window.location = new URL('https://example.com/screenferry?foo=bar') as any;

      const link = generateReceiverLink();
      expect(link).toContain('foo=bar');
      expect(link).toContain('#recv');

      window.location = originalLocation;
    });
  });

  describe('generateSenderLink', () => {
    it('should generate URL with #send hash', () => {
      const originalLocation = window.location;
      delete (window as any).location;
      window.location = new URL('https://example.com/screenferry') as any;

      const link = generateSenderLink();
      expect(link).toContain('#send');

      window.location = originalLocation;
    });

    it('should preserve existing URL components', () => {
      const originalLocation = window.location;
      delete (window as any).location;
      window.location = new URL('https://example.com/screenferry?foo=bar') as any;

      const link = generateSenderLink();
      expect(link).toContain('foo=bar');
      expect(link).toContain('#send');

      window.location = originalLocation;
    });
  });

  describe('switchToReceiverMode', () => {
    it('should set window.location.hash to #recv', () => {
      const originalLocation = window.location;
      delete (window as any).location;
      window.location = new URL('https://example.com/screenferry') as any;

      switchToReceiverMode();
      expect(window.location.hash).toBe('#recv');

      window.location = originalLocation;
    });
  });

  describe('switchToSenderMode', () => {
    it('should set window.location.hash to #send', () => {
      const originalLocation = window.location;
      delete (window as any).location;
      window.location = new URL('https://example.com/screenferry') as any;

      switchToSenderMode();
      expect(window.location.hash).toBe('#send');

      window.location = originalLocation;
    });
  });

  describe('getCurrentMode', () => {
    it('should return current mode from window.location.hash', () => {
      const originalLocation = window.location;
      delete (window as any).location;

      window.location = new URL('https://example.com/screenferry#recv') as any;
      expect(getCurrentMode()).toBe(AppMode.RECEIVER);

      window.location = new URL('https://example.com/screenferry#send') as any;
      expect(getCurrentMode()).toBe(AppMode.SENDER);

      window.location = originalLocation;
    });

    it('should default to receiver mode for empty hash', () => {
      const originalLocation = window.location;
      delete (window as any).location;
      window.location = new URL('https://example.com/screenferry') as any;

      expect(getCurrentMode()).toBe(AppMode.RECEIVER);

      window.location = originalLocation;
    });
  });

  describe('F8 Feature Integration', () => {
    it('should support complete pairing workflow', () => {
      const originalLocation = window.location;
      delete (window as any).location;
      window.location = new URL('https://example.com/screenferry') as any;

      // 1. Sender generates receiver deep link
      const receiverLink = generateReceiverLink();
      expect(receiverLink).toContain('#recv');

      // 2. Receiver opens link and lands in receive mode
      window.location = new URL(receiverLink) as any;
      expect(getCurrentMode()).toBe(AppMode.RECEIVER);

      // 3. Sender can switch to receiver mode
      switchToReceiverMode();
      expect(window.location.hash).toBe('#recv');

      // 4. Receiver can switch to sender mode
      switchToSenderMode();
      expect(window.location.hash).toBe('#send');
      expect(getCurrentMode()).toBe(AppMode.SENDER);

      window.location = originalLocation;
    });

    it('should handle case-insensitive hash parsing', () => {
      expect(parseModeFromHash('#RECV')).toBe(AppMode.RECEIVER);
      expect(parseModeFromHash('#Recv')).toBe(AppMode.RECEIVER);
      expect(parseModeFromHash('#SEND')).toBe(AppMode.SENDER);
      expect(parseModeFromHash('#Send')).toBe(AppMode.SENDER);
    });
  });
});

/**
 * Sender splash UI tests (F8: Pairing splash QR)
 *
 * Tests QR code generation, file drop zone, and sender splash UI functionality.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { createSenderSplashUI, type SenderSplashUI } from '../src/platform/sender-splash-ui.js';
import { generateReceiverLink } from '../src/platform/role-inference.js';

describe('sender-splash-ui', () => {
  let container: HTMLElement;
  let senderUI: SenderSplashUI;

  beforeEach(() => {
    // Create a fresh container for each test
    container = document.createElement('div');
    document.body.appendChild(container);
  });

  afterEach(() => {
    // Clean up UI
    if (senderUI && 'stop' in senderUI) {
      senderUI.stop();
    }
    document.body.removeChild(container);
  });

  describe('UI Creation', () => {
    it('should create sender splash UI with QR code container', () => {
      senderUI = createSenderSplashUI({
        container,
      });

      expect(container.querySelector('.qr-code-container')).toBeTruthy();
      expect(container.querySelector('#pairing-qr-code')).toBeTruthy();
    });

    it('should create file drop zone', () => {
      senderUI = createSenderSplashUI({
        container,
      });

      expect(container.querySelector('.file-drop-zone')).toBeTruthy();
    });

    it('should create instructions panel', () => {
      senderUI = createSenderSplashUI({
        container,
      });

      const instructions = container.querySelector('h2');
      expect(instructions?.textContent).toContain('Pairing Instructions');
    });

    it('should create switch mode button', () => {
      senderUI = createSenderSplashUI({
        container,
      });

      const button = container.querySelector('button');
      expect(button?.textContent).toContain('Switch to Receiver Mode');
    });
  });

  describe('QR Code Generation', () => {
    it('should generate QR code on start', async () => {
      senderUI = createSenderSplashUI({
        container,
      });

      await senderUI.start();

      const qrCanvas = senderUI.getQRCanvas();
      expect(qrCanvas).toBeTruthy();
      expect(qrCanvas.width).toBeGreaterThan(0);
      expect(qrCanvas.height).toBeGreaterThan(0);
    });

    it('should generate QR code with receiver deep link', async () => {
      senderUI = createSenderSplashUI({
        container,
      });

      await senderUI.start();

      const receiverLink = generateReceiverLink();
      const qrCanvas = senderUI.getQRCanvas();

      // QR code generation should have succeeded
      expect(qrCanvas).toBeTruthy();
    });

    it('should use custom QR config when provided', async () => {
      senderUI = createSenderSplashUI({
        container,
        qrConfig: {
          size: 200,
          margin: 4,
          color: {
            dark: '#FF0000',
            light: '#00FF00',
          },
        },
      });

      await senderUI.start();

      const qrCanvas = senderUI.getQRCanvas();
      expect(qrCanvas.width).toBe(200);
    });
  });

  describe('File Drop Zone', () => {
    it('should call onFileDrop callback when file is dropped', async () => {
      let droppedFile: File | null = null;

      senderUI = createSenderSplashUI({
        container,
        onFileDrop: (file: File) => {
          droppedFile = file;
        },
      });

      await senderUI.start();

      const dropZone = senderUI.getDropZone();
      const file = new File(['test'], 'test.txt', { type: 'text/plain' });

      // Create a mock drag event
      const dropEvent = new DragEvent('drop', {
        bubbles: true,
        dataTransfer: new DataTransfer(),
      });
      (dropEvent.dataTransfer as DataTransfer).items.add(file);

      dropZone.dispatchEvent(dropEvent);

      // Note: Due to storage capacity check, we need to wait for async operation
      // For now, just verify the drop zone exists and handles events
      expect(dropZone).toBeTruthy();
    });

    it('should update drop zone text when file is selected', async () => {
      senderUI = createSenderSplashUI({
        container,
        onFileDrop: () => {},
      });

      await senderUI.start();

      const dropZone = senderUI.getDropZone();
      expect(dropZone).toBeTruthy();
      expect(dropZone.textContent).toContain('Drop a file here to send');
    });
  });

  describe('F8 Feature Integration', () => {
    it('should display pairing instructions for both sender and receiver', async () => {
      senderUI = createSenderSplashUI({
        container,
      });

      await senderUI.start();

      const instructions = container.querySelector('h2');
      expect(instructions?.textContent).toContain('Pairing Instructions');

      const instructionsList = container.querySelector('ol');
      expect(instructionsList).toBeTruthy();
      expect(instructionsList?.textContent).toContain('Receiver');
      expect(instructionsList?.textContent).toContain('Sender');
    });

    it('should show offline limitation notice', async () => {
      senderUI = createSenderSplashUI({
        container,
      });

      await senderUI.start();

      const content = container.textContent || '';
      expect(content).toContain('online');
      expect(content).toContain('air-gapped');
    });

    it('should support complete pairing workflow', async () => {
      senderUI = createSenderSplashUI({
        container,
      });

      await senderUI.start();

      // 1. QR code is generated
      const qrCanvas = senderUI.getQRCanvas();
      expect(qrCanvas).toBeTruthy();

      // 2. File drop zone is ready
      const dropZone = senderUI.getDropZone();
      expect(dropZone).toBeTruthy();

      // 3. Switch to receiver button is available
      const switchButton = container.querySelector('button');
      expect(switchButton).toBeTruthy();
      expect(switchButton?.textContent).toContain('Switch to Receiver Mode');

      // 4. Instructions are displayed
      const instructions = container.querySelector('h2');
      expect(instructions?.textContent).toContain('Pairing Instructions');
    });
  });

  describe('QR Code Styling', () => {
    it('should apply proper styling to QR code container', async () => {
      senderUI = createSenderSplashUI({
        container,
      });

      await senderUI.start();

      const qrContainer = container.querySelector('.qr-code-container');
      expect(qrContainer).toBeTruthy();

      const computedStyle = window.getComputedStyle(qrContainer!);
      expect(computedStyle.backgroundColor).toBe('rgb(255, 255, 255)');
      expect(computedStyle.padding).not.toBe('0px');
    });

    it('should apply proper styling to drop zone', async () => {
      senderUI = createSenderSplashUI({
        container,
      });

      await senderUI.start();

      const dropZone = container.querySelector('.file-drop-zone');
      expect(dropZone).toBeTruthy();

      const computedStyle = window.getComputedStyle(dropZone!);
      expect(computedStyle.border).toContain('dashed');
    });
  });

  describe('Feature Highlights', () => {
    it('should display ScreenFerry features', async () => {
      senderUI = createSenderSplashUI({
        container,
      });

      await senderUI.start();

      const features = container.querySelector('h2');
      expect(features?.textContent).toContain('ScreenFerry Features');

      const featureList = container.querySelector('ul');
      expect(featureList).toBeTruthy();
      expect(featureList?.textContent).toContain('Smart reticle');
      expect(featureList?.textContent).toContain('Fast transfers');
      expect(featureList?.textContent).toContain('Privacy-first');
      expect(featureList?.textContent).toContain('Air-gapped');
    });
  });
});

